with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co01zf706d', 'practice', 'Écoute B1 : une nouvelle école', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-nouvelle-ecole.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• ouvrir ses portes (expression) : mở cửa, khai trương\n• le car (nom masculin) : xe buýt đường dài\n• un panneau solaire (expression) : tấm pin mặt trời\n• ravi, ravie (adjectif) : rất vui\n• un habitant (nom masculin) : cư dân","explications":"• Lần nghe đầu chỉ cần bắt: chuyện gì, ở đâu, ai nói.\n• Câu mở đầu của phóng viên thường chứa ý chính của cả bài.","isPremium":true,"price":19000,"kyNang":"B1-CO-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T17:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufw000', 'b1co01zf706d', 1, 'qcm', 'De quoi parle ce reportage ?', '{"options":["de l''ouverture d''une école dans un village","d''un nouveau car scolaire","de la fermeture d''une école"]}'::jsonb, '{"answer":0}'::jsonb, '« une nouvelle école a ouvert ses portes lundi ».'), ('qmw0ouufw001', 'b1co01zf706d', 2, 'qcm', 'Qui parle dans la deuxième partie ?', '{"options":["une mère d''élève","le maire du village","la directrice de l''école"]}'::jsonb, '{"answer":2}'::jsonb, '« Nous avons rencontré la directrice, Claire Morel ».'), ('qmw0ouufw002', 'b1co01zf706d', 3, 'fill', 'Complétez avec ce que vous entendez : Avant, les enfants devaient prendre le car pendant ______ minutes.', '{}'::jsonb, '{"accepted":"quarante|40"}'::jsonb, 'Quarante là 40; đừng nhầm với quatorze (14).'), ('qmw0ouufw003', 'b1co01zf706d', 4, 'qcm', 'Selon la directrice, les parents sont…', '{"options":["pas d''accord","très contents","inquiets"]}'::jsonb, '{"answer":1}'::jsonb, '« Les parents sont ravis »: ravi nghĩa là rất vui.'), ('qmw0ouufw004', 'b1co01zf706d', 5, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufw008","texte":"le samedi matin."},{"id":"emw0ouufw006","texte":"d''ouvrir la bibliothèque de l''école"},{"id":"emw0ouufw007","texte":"aux habitants,"},{"id":"emw0ouufw005","texte":"Notre projet, c''est aussi"}]}'::jsonb, '{"elements":[{"id":"emw0ouufw005","texte":"Notre projet, c''est aussi"},{"id":"emw0ouufw006","texte":"d''ouvrir la bibliothèque de l''école"},{"id":"emw0ouufw007","texte":"aux habitants,"},{"id":"emw0ouufw008","texte":"le samedi matin."}]}'::jsonb, 'Câu bắt đầu bằng « Notre projet » rồi tới việc làm, cuối cùng là thời gian.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co024bm06e', 'practice', 'Écoute B1 : un festival dans ma ville', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-festival-port.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un bénévole (nom masculin) : tình nguyện viên\n• l''accueil (nom masculin) : đón tiếp\n• en échange de (expression) : đổi lại\n• un pass (nom masculin) : thẻ vào cửa\n• une inscription (nom féminin) : sự đăng ký","explications":"• Câu hỏi « but du message » hỏi người nói MUỐN người nghe làm gì.\n• « Aucune… n''est demandée, mais » báo trước điều kiện thật nằm sau mais.","isPremium":true,"price":19000,"kyNang":"B1-CO-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-03T17:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufw009', 'b1co024bm06e', 1, 'qcm', 'Quel est le but principal de ce message ?', '{"options":["vendre des billets de concert","annoncer l''annulation du festival","trouver des bénévoles pour le festival"]}'::jsonb, '{"answer":2}'::jsonb, '« nous cherchons cent cinquante bénévoles »: đây là mục đích của thông báo.'), ('qmw0ouufx00a', 'b1co024bm06e', 2, 'fill', 'Complétez avec ce que vous entendez : Le festival Les Nuits du Port revient du ______ au quinze juillet.', '{}'::jsonb, '{"accepted":"douze|12"}'::jsonb, 'Douze là 12.'), ('qmw0ouufx00b', 'b1co024bm06e', 3, 'qcm', 'Que reçoivent les bénévoles ?', '{"options":["un salaire","un pass pour les concerts et un tee-shirt","des boissons gratuites"]}'::jsonb, '{"answer":1}'::jsonb, '« un pass gratuit pour tous les concerts et un tee-shirt du festival ».'), ('qmw0ouufx00c', 'b1co024bm06e', 4, 'qcm', 'Pour participer, il faut…', '{"options":["avoir de l''expérience","avoir au moins 18 ans","habiter près du port"]}'::jsonb, '{"answer":1}'::jsonb, '« Aucune expérience n''est demandée, mais il faut avoir au moins dix-huit ans ».'), ('qmw0ouufx00d', 'b1co024bm06e', 5, 'fill', 'Complétez avec ce que vous entendez : Inscriptions sur notre site avant le ______ juin.', '{}'::jsonb, '{"accepted":"trente|30"}'::jsonb, 'Trente là 30.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co038nt06f', 'practice', 'Écoute B1 : les écrans chez les jeunes', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-ecrans-jeunes.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un adolescent (nom masculin) : thiếu niên\n• une enquête (nom féminin) : cuộc khảo sát\n• en moyenne (expression) : trung bình\n• en dehors de (expression) : ngoài\n• interdire (verbe) : cấm","explications":"• Câu đầu của đề thường hỏi ý tổng quát: trả lời ngay sau lần nghe thứ nhất.\n• Bài có nhiều con số (5, 7, 22): ghi mỗi số kèm một từ khoá.","isPremium":true,"price":19000,"kyNang":"B1-CO-1","vong":"on","thuTu":5}'::jsonb, '2026-11-03T17:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufx00e', 'b1co038nt06f', 1, 'qcm', 'Quel est le thème de l''émission ?', '{"options":["les jeux vidéo à l''école","le temps des adolescents devant les écrans","le sommeil des jeunes enfants"]}'::jsonb, '{"answer":1}'::jsonb, '« nous parlons du temps que les adolescents passent devant les écrans ».'), ('qmw0ouufx00f', 'b1co038nt06f', 2, 'fill', 'Complétez avec ce que vous entendez : Les jeunes passent en moyenne ______ heures par jour sur leur téléphone.', '{}'::jsonb, '{"accepted":"cinq|5"}'::jsonb, 'Cinq là 5. Sept là số giờ ngủ, không phải giờ dùng điện thoại.'), ('qmw0ouufx00g', 'b1co038nt06f', 3, 'qcm', 'Selon la psychologue, le moment le plus problématique est…', '{"options":["le soir","pendant les cours","le matin"]}'::jsonb, '{"answer":0}'::jsonb, '« c''est surtout le soir ».'), ('qmw0ouufx00h', 'b1co038nt06f', 4, 'qcm', 'Que conseille-t-elle aux parents ?', '{"options":["acheter un réveil","discuter plutôt qu''interdire","interdire le téléphone"]}'::jsonb, '{"answer":1}'::jsonb, '« ne pas interdire, mais discuter ».'), ('qmw0ouufx00i', 'b1co038nt06f', 5, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufx00k","texte":"restent dans la cuisine"},{"id":"emw0ouufx00j","texte":"tous les téléphones"},{"id":"emw0ouufx00l","texte":"après vingt-deux heures."}]}'::jsonb, '{"elements":[{"id":"emw0ouufx00j","texte":"tous les téléphones"},{"id":"emw0ouufx00k","texte":"restent dans la cuisine"},{"id":"emw0ouufx00l","texte":"après vingt-deux heures."}]}'::jsonb, 'Chủ ngữ, động từ, rồi thời gian.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co04c9v06g', 'practice', 'Écoute B1 : de quoi parle-t-on ?', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-de-quoi-parle.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une chute de neige (expression) : tuyết rơi\n• la préfecture (nom féminin) : tỉnh trưởng, cơ quan tỉnh\n• un automobiliste (nom masculin) : người lái ô tô\n• des chaînes (nom féminin pluriel) : xích chống trượt\n• un piéton (nom masculin) : người đi bộ","explications":"• Ba tài liệu ngắn liền nhau: sau mỗi tài liệu, tự nói một câu « đây là loại gì ».\n• Nhận loại tài liệu qua từ khoá: attention (cảnh báo), avec + tên sản phẩm (quảng cáo), sera fermé (tin tức).","isPremium":true,"price":19000,"kyNang":"B1-CO-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T17:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufx00m', 'b1co04c9v06g', 1, 'qcm', 'Document 1 : c''est…', '{"options":["une alerte météo","un bulletin sportif","une publicité"]}'::jsonb, '{"answer":0}'::jsonb, '« de fortes chutes de neige sont attendues cette nuit ».'), ('qmw0ouufx00n', 'b1co04c9v06g', 2, 'fill', 'Complétez avec ce que vous entendez : La préfecture demande d''équiper leur voiture de ______.', '{}'::jsonb, '{"accepted":"chaînes|chaines"}'::jsonb, 'Des chaînes là xích chống trượt cho bánh xe.'), ('qmw0ouufx00o', 'b1co04c9v06g', 3, 'qcm', 'Document 2 : on fait la publicité pour…', '{"options":["une école de langues en ville","un voyage en Angleterre","une application pour apprendre les langues"]}'::jsonb, '{"answer":2}'::jsonb, '« l''application pour apprendre une langue en dix minutes par jour ».'), ('qmw0ouufx00p', 'b1co04c9v06g', 4, 'qcm', 'Document 2 : le premier mois est…', '{"options":["gratuit","à moitié prix","réservé aux étudiants"]}'::jsonb, '{"answer":0}'::jsonb, '« Le premier mois est gratuit ».'), ('qmw0ouufx00q', 'b1co04c9v06g', 5, 'qcm', 'Document 3 : l''information concerne…', '{"options":["un accident sur un pont","des travaux sur un pont","une nouvelle ligne de bus"]}'::jsonb, '{"answer":1}'::jsonb, '« le grand pont sur la Loire sera fermé aux voitures pendant six mois à partir de lundi, pour des travaux ».'), ('qmw0ouufx00r', 'b1co04c9v06g', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufx00t","texte":"pourront continuer"},{"id":"emw0ouufx00u","texte":"à passer."},{"id":"emw0ouufx00s","texte":"Les piétons et les vélos"}]}'::jsonb, '{"elements":[{"id":"emw0ouufx00s","texte":"Les piétons et les vélos"},{"id":"emw0ouufx00t","texte":"pourront continuer"},{"id":"emw0ouufx00u","texte":"à passer."}]}'::jsonb, 'Chủ ngữ, pourront + động từ nguyên mẫu.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co05h8y06h', 'practice', 'Écoute B1 : les Français et le sport', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-francais-sport.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une enquête (nom féminin) : cuộc khảo sát\n• désormais (adverbe) : từ nay\n• en revanche (expression) : ngược lại\n• le manque de (expression) : sự thiếu\n• citer (verbe) : nêu, nhắc tới","explications":"• « Six sur dix », « un sur deux »: tiếng Pháp hay nói tỉ lệ kiểu này thay cho phần trăm.\n• Devant, avant: nghe kỹ để biết cái nào đứng thứ nhất.","kyNang":"B1-CO-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T17:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufx00v', 'b1co05h8y06h', 1, 'fill', 'Complétez avec ce que vous entendez : D''après une enquête publiée ce matin par l''institut Opinion Plus, ______ Français sur dix font du sport au moins une fois par semaine.', '{}'::jsonb, '{"accepted":"six|6"}'::jsonb, 'Six sur dix là 60 %.'), ('qmw0ouufx00w', 'b1co05h8y06h', 2, 'qcm', 'Il y a dix ans, les Français sportifs étaient…', '{"options":["40 %","55 %","45 %"]}'::jsonb, '{"answer":2}'::jsonb, '« quand ils n''étaient que quarante-cinq pour cent ».'), ('qmw0ouufx00x', 'b1co05h8y06h', 3, 'qcm', 'Quel est le sport préféré des Français ?', '{"options":["la course à pied","la marche","le vélo"]}'::jsonb, '{"answer":1}'::jsonb, '« Le sport préféré reste la marche, devant la course à pied et le vélo »: devant là đứng trước.'), ('qmw0ouufx00y', 'b1co05h8y06h', 4, 'qcm', 'Selon l''enquête, les femmes…', '{"options":["préfèrent le vélo","font autant de sport que les hommes","font moins de sport que les hommes"]}'::jsonb, '{"answer":1}'::jsonb, '« Les femmes sont désormais aussi nombreuses que les hommes ».'), ('qmw0ouufx00z', 'b1co05h8y06h', 5, 'qcm', 'Chez les 18-24 ans, …', '{"options":["tout le monde fait du sport","la pratique du sport baisse","la pratique augmente"]}'::jsonb, '{"answer":1}'::jsonb, '« les jeunes de dix-huit à vingt-quatre ans font moins de sport qu''avant ».'), ('qmw0ouufx010', 'b1co05h8y06h', 6, 'fill', 'Complétez avec ce que vous entendez : Le manque de ______ est la raison la plus souvent citée.', '{}'::jsonb, '{"accepted":"temps"}'::jsonb, 'Le manque de temps: thiếu thời gian.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co06kvs06i', 'practice', 'Écoute B1 : pour ou contre l''uniforme', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-uniforme.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un uniforme (nom masculin) : đồng phục\n• une marque (nom féminin) : nhãn hiệu\n• modeste (adjectif) : khó khăn, bình dân\n• une inégalité (nom féminin) : sự bất bình đẳng\n• un premier pas (expression) : bước đầu","explications":"• Bài tranh luận: ghi tên mỗi người kèm « pour » hoặc « contre » ngay từ đầu.\n• « Je ne suis pas d''accord. D''abord… Ensuite… Et puis… » báo trước một danh sách lý do.","isPremium":true,"price":19000,"kyNang":"B1-CO-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-03T17:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy011', 'b1co06kvs06i', 1, 'qcm', 'Qui est favorable à l''uniforme ?', '{"options":["les deux invités","la professeure","le père de famille"]}'::jsonb, '{"answer":2}'::jsonb, 'Marc Lebrun, người cha: « Moi, je suis pour ».'), ('qmw0ouufy012', 'b1co06kvs06i', 2, 'qcm', 'Selon Marc, l''uniforme permet…', '{"options":["d''éviter la compétition entre les marques","d''améliorer les notes","de faire des économies"]}'::jsonb, '{"answer":0}'::jsonb, '« il n''y a plus de compétition entre les marques ».'), ('qmw0ouufy013', 'b1co06kvs06i', 3, 'fill', 'Complétez avec ce que vous entendez : Un uniforme coûte cher, environ ______ euros par an.', '{}'::jsonb, '{"accepted":"deux cents|200|deux-cents"}'::jsonb, 'Đây là ý