with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co1364u06p', 'practice', 'Écoute B1 : la parole aux auditeurs', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-parole-auditeurs.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un auditeur (nom masculin) : thính giả\n• un commerçant (nom masculin) : người buôn bán\n• le chiffre d''affaires (expression) : doanh thu\n• partagé, partagée (adjectif) : phân vân, nửa đồng ý nửa không\n• une navette (nom féminin) : xe đưa đón","explications":"• Mỗi thính giả một thái độ: ghi tên kèm +, -, hoặc ± ngay khi nghe.\n• « Je suis partagé » và « L''idée est bonne, mais » là dấu hiệu ý kiến trung lập.","isPremium":true,"price":19000,"kyNang":"B1-CO-3","vong":"on","thuTu":5}'::jsonb, '2026-11-03T17:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy02z', 'b1co1364u06p', 1, 'qcm', 'Quelle est l''attitude de Gérard ?', '{"options":["il est enthousiaste","il n''a pas d''avis","il est opposé et inquiet"]}'::jsonb, '{"answer":2}'::jsonb, '« franchement, c''est une catastrophe ».'), ('qmw0ouufy030', 'b1co1364u06p', 2, 'fill', 'Complétez avec ce que vous entendez : J''ai perdu ______ pour cent de mon chiffre d''affaires.', '{}'::jsonb, '{"accepted":"vingt|20"}'::jsonb, 'Vingt pour cent là 20 %.'), ('qmw0ouufy031', 'b1co1364u06p', 3, 'qcm', 'Nadia trouve la mesure…', '{"options":["excellente","dangereuse","inutile"]}'::jsonb, '{"answer":0}'::jsonb, '« je trouve ça génial ».'), ('qmw0ouufy032', 'b1co1364u06p', 4, 'qcm', 'Michel est…', '{"options":["totalement contre","partagé","totalement pour"]}'::jsonb, '{"answer":1}'::jsonb, '« Je suis partagé. L''idée est bonne, mais… »'), ('qmw0ouufy033', 'b1co1364u06p', 5, 'qcm', 'Que propose Michel ?', '{"options":["des parkings gratuits","rouvrir le centre aux voitures","plus de bus et de navettes gratuites"]}'::jsonb, '{"answer":2}'::jsonb, '« Il faudrait plus de bus et de navettes gratuites ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co148tv06q', 'practice', 'Écoute B1 : que ressent-il ?', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-que-ressent.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• en avoir assez (expression) : chán ngấy\n• fier, fière (adjectif) : tự hào\n• une occasion (nom féminin) : cơ hội\n• annuler (verbe) : huỷ\n• soulagé, soulagée (adjectif) : nhẹ nhõm","explications":"• Bốn giọng, bốn cảm xúc: tìm từ chỉ cảm xúc trong câu cuối mỗi đoạn.\n• J''en ai assez (bực), si fière (tự hào), je ne sais pas si (do dự), déçue (thất vọng).","isPremium":true,"price":19000,"kyNang":"B1-CO-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T17:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy034', 'b1co148tv06q', 1, 'qcm', 'Document 1 : la personne est…', '{"options":["amusée","exaspérée","inquiète"]}'::jsonb, '{"answer":1}'::jsonb, '« J''en ai vraiment assez ».'), ('qmw0ouufy035', 'b1co148tv06q', 2, 'fill', 'Complétez avec ce que vous entendez : C''est la troisième fois cette semaine que ce train arrive avec ______ minutes de retard.', '{}'::jsonb, '{"accepted":"vingt|20"}'::jsonb, 'Vingt là 20.'), ('qmw0ouufy036', 'b1co148tv06q', 3, 'qcm', 'Document 2 : la mère est…', '{"options":["fière","jalouse","triste"]}'::jsonb, '{"answer":0}'::jsonb, '« Je suis si fière de lui ».'), ('qmw0ouufy037', 'b1co148tv06q', 4, 'qcm', 'Document 3 : l''homme est…', '{"options":["furieux","hésitant","décidé"]}'::jsonb, '{"answer":1}'::jsonb, '« Je ne sais pas si je dois accepter ce poste ».'), ('qmw0ouufy038', 'b1co148tv06q', 5, 'qcm', 'Document 4 : la jeune femme est…', '{"options":["soulagée","déçue","impatiente"]}'::jsonb, '{"answer":1}'::jsonb, '« Je suis tellement déçue ».'), ('qmw0ouufy039', 'b1co148tv06q', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy03b","texte":"réfléchir"},{"id":"emw0ouufy03a","texte":"Je vais"},{"id":"emw0ouufy03c","texte":"encore."}]}'::jsonb, '{"elements":[{"id":"emw0ouufy03a","texte":"Je vais"},{"id":"emw0ouufy03b","texte":"réfléchir"},{"id":"emw0ouufy03c","texte":"encore."}]}'::jsonb, 'Je vais + động từ nguyên mẫu.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co15bq006r', 'practice', 'Écoute B1 : travailler de chez soi', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-teletravail.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un graphiste (nom masculin) : nhà thiết kế đồ hoạ\n• un avantage (nom masculin) : ưu điểm\n• un inconvénient (nom masculin) : nhược điểm\n• la solitude (nom féminin) : sự cô đơn\n• éteindre (verbe) : tắt","explications":"• Câu hỏi của người dẫn chia bài thành phần: avantages rồi inconvénients.\n• D''abord, surtout là từ nhấn ý quan trọng nhất.","kyNang":"B1-CO-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T17:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy03d', 'b1co15bq006r', 1, 'fill', 'Complétez avec ce que vous entendez : Je ne perds plus une heure et ______ par jour dans les transports.', '{}'::jsonb, '{"accepted":"demie|demi"}'::jsonb, 'Une heure et demie: một tiếng rưỡi.'), ('qmw0ouufy03e', 'b1co15bq006r', 2, 'qcm', 'Au bureau, Sarah travaillait…', '{"options":["dans une pièce partagée et bruyante","seule dans un bureau","dans un café"]}'::jsonb, '{"answer":0}'::jsonb, '« on était douze dans la même pièce, avec beaucoup de bruit ».'), ('qmw0ouufy03f', 'b1co15bq006r', 3, 'qcm', 'Le principal inconvénient selon Sarah est…', '{"options":["le salaire","la solitude","le manque de matériel"]}'::jsonb, '{"answer":1}'::jsonb, '« La solitude, surtout ».'), ('qmw0ouufy03g', 'b1co15bq006r', 4, 'qcm', 'Pourquoi est-il difficile de s''arrêter ?', '{"options":["elle a trop de travail","son chef l''appelle le soir","l''ordinateur reste dans le salon"]}'::jsonb, '{"answer":2}'::jsonb, '« l''ordinateur est toujours là, sur la table du salon ».'), ('qmw0ouufy03h', 'b1co15bq006r', 5, 'qcm', 'Le jeudi, Sarah…', '{"options":["ne travaille pas","va au bureau voir ses collègues","travaille dans un café"]}'::jsonb, '{"answer":1}'::jsonb, '« je vais au bureau le jeudi, pour voir mes collègues ».'), ('qmw0ouufy03i', 'b1co15bq006r', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy03l","texte":"j''éteins tout."},{"id":"emw0ouufy03k","texte":"à dix-neuf heures,"},{"id":"emw0ouufy03j","texte":"le soir,"}]}'::jsonb, '{"elements":[{"id":"emw0ouufy03j","texte":"le soir,"},{"id":"emw0ouufy03k","texte":"à dix-neuf heures,"},{"id":"emw0ouufy03l","texte":"j''éteins tout."}]}'::jsonb, 'Thời gian trước, hành động sau.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co16f2i06s', 'practice', 'Écoute B1 : changer de métier à 40 ans', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-changer-metier.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un banquier (nom masculin) : nhân viên ngân hàng\n• gagner sa vie (expression) : kiếm sống\n• s''ennuyer (verbe) : buồn chán\n• un artisan (nom masculin) : thợ thủ công\n• concret, concrète (adjectif) : cụ thể, hữu hình","explications":"• « Si, bien sûr » trả lời một câu hỏi phủ định: nghĩa là CÓ, khó lắm.\n• Deux fois moins: bằng một nửa. Đừng nhầm với deux fois plus.","isPremium":true,"price":19000,"kyNang":"B1-CO-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T17:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy03m', 'b1co16f2i06s', 1, 'fill', 'Complétez avec ce que vous entendez : Julien Mercier a été banquier pendant ______ ans.', '{}'::jsonb, '{"accepted":"quinze|15"}'::jsonb, 'Quinze là 15; quarante et un là tuổi lúc đổi nghề.'), ('qmw0ouufy03n', 'b1co16f2i06s', 2, 'qcm', 'Pourquoi a-t-il quitté la banque ?', '{"options":["il gagnait trop peu","il avait perdu son poste","il s''ennuyait"]}'::jsonb, '{"answer":2}'::jsonb, '« Je gagnais bien ma vie, mais je m''ennuyais ».'), ('qmw0ouufy03o', 'b1co16f2i06s', 3, 'qcm', 'Qu''est-ce qui a déclenché son projet ?', '{"options":["un reportage à la télévision","un conseil de sa femme","un stage de pain un week-end"]}'::jsonb, '{"answer":2}'::jsonb, '« Un week-end, j''ai fait un stage de pain chez un artisan ».'), ('qmw0ouufy03p', 'b1co16f2i06s', 4, 'qcm', 'Pendant sa formation, …', '{"options":["sa femme a payé la plupart des dépenses","il a continué à travailler à la banque","il a emprunté à ses parents"]}'::jsonb, '{"answer":0}'::jsonb, '« ma femme a dû payer presque toutes les dépenses de la famille ».'), ('qmw0ouufy03q', 'b1co16f2i06s', 5, 'qcm', 'Aujourd''hui, Julien gagne…', '{"options":["autant qu''avant","deux fois plus qu''avant","deux fois moins qu''avant"]}'::jsonb, '{"answer":2}'::jsonb, '« je gagne deux fois moins qu''avant ».'), ('qmw0ouufy03r', 'b1co16f2i06s', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy03s","texte":"je fais quelque chose"},{"id":"emw0ouufy03u","texte":"et je vois"},{"id":"emw0ouufy03v","texte":"les clients sourire."},{"id":"emw0ouufy03t","texte":"de concret,"}]}'::jsonb, '{"elements":[{"id":"emw0ouufy03s","texte":"je fais quelque chose"},{"id":"emw0ouufy03t","texte":"de concret,"},{"id":"emw0ouufy03u","texte":"et je vois"},{"id":"emw0ouufy03v","texte":"les clients sourire."}]}'::jsonb, 'Hai lý do khiến Julien hạnh phúc.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co17ksk06t', 'practice', 'Écoute B1 : mon premier stage', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-premier-stage.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un stage (nom masculin) : kỳ thực tập\n• une tutrice (nom féminin) : người hướng dẫn\n• confier (verbe) : giao phó\n• une campagne (nom féminin) : chiến dịch\n• suffire (verbe) : đủ","explications":"• Bài kể theo thời gian: les deux premières semaines, puis, mais. Ghi chú theo các mốc đó.\n• « Ce qui ne suffit pas… donc… » nối nguyên nhân và kết quả.","isPremium":true,"price":19000,"kyNang":"B1-CO-4","vong":"hoc","thuTu":4}'::jsonb, '2026-11-03T17:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy03w', 'b1co17ksk06t', 1, 'qcm', 'Où Maëlle a-t-elle fait son stage ?', '{"options":["dans un festival de cinéma","dans une agence de publicité","dans une école de communication"]}'::jsonb, '{"answer":1}'::jsonb, '« dans une petite agence de publicité à Marseille ».'), ('qmw0ouufy03x', 'b1co17ksk06t', 2, 'fill', 'Complétez avec ce que vous entendez : J''ai fait mon stage dans une petite agence de publicité à Marseille, pendant ______ mois.', '{}'::jsonb, '{"accepted":"trois|3"}'::jsonb, 'Trois là 3.'), ('qmw0ouufy03y', 'b1co17ksk06t', 3, 'qcm', 'Au début, elle…', '{"options":["faisait des tâches peu intéressantes","écrivait déjà des textes","dirigeait un projet"]}'::jsonb, '{"answer":0}'::jsonb, '« je faisais surtout des photocopies et je préparais le café ».'), ('qmw0ouufy03z', 'b1co17ksk06t', 4, 'qcm', 'Son vrai projet concernait…', '{"options":["un festival de cinéma","un club de sport","un nouveau restaurant"]}'::jsonb, '{"answer":0}'::jsonb, '« la campagne d''un festival de cinéma ».'), ('qmw0ouufy040', 'b1co17ksk06t', 5, 'qcm', 'Avec son salaire de stagiaire, …', '{"options":["elle vivait très bien","elle a pu économiser","elle avait besoin de l''aide de ses parents"]}'::jsonb, '{"answer":2}'::jsonb, '« ce qui ne suffit pas pour vivre à Marseille, donc mes parents m''ont aidée ».'), ('qmw0ouufy041', 'b1co17ksk06t', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy043","texte":"un contrat"},{"id":"emw0ouufy042","texte":"l''agence m''a proposé"},{"id":"emw0ouufy044","texte":"pour l''été."}]}'::jsonb, '{"elements":[{"id":"emw0ouufy042","texte":"l''agence m''a proposé"},{"id":"emw0ouufy043","texte":"un contrat"},{"id":"emw0ouufy044","texte":"pour l''été."}]}'::jsonb, 'Kết quả cuối cùng của kỳ thực tập.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co18r2306u', 'practice', 'Écoute B1 : les métiers de demain', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-metiers-demain.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• recruter (verbe) : tuyển dụng\n• un aide-soignant (nom masculin) : hộ lý\n• vieillir (verbe) : già đi\n• la transition écologique (expression) : chuyển đổi xanh\n• une compétence (nom féminin) : năng lực","explications":"• D''abord, ensuite, enfin chia bài thành ba phần: mỗi phần một lĩnh vực.\n• Car báo nguyên nhân, donc báo kết quả.","isPremium":true,"price":19000,"kyNang":"B1-CO-4","vong":"on","thuTu":5}'::jsonb, '2026-11-03T17:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy045', 'b1co18r2306u', 1, 'qcm', 'Ce document est…', '{"options":["une publicité pour une école","un entretien d''embauche","un bulletin d''information sur l''emploi"]}'::jsonb, '{"answer":2}'::jsonb, 'Bản tin nói về « Quels métiers recruteront le plus dans dix ans ».'), ('qmw0ouufy046', 'b1co18r2306u', 2, 'fill', 'Complétez avec ce que vous entendez : Selon l''étude, les besoins seront très forts dans ______ domaines.', '{}'::jsonb, '{"accepted":"trois|3"}'::jsonb, 'Ba lĩnh vực: santé, transition écologique, numérique.'), ('qmw0ouufy047', 'b1co18r2306u', 3, 'qcm', 'Pourquoi manquera-t-il des infirmiers ?', '{"options":["les écoles ferment","la population vieillit","les salaires sont bas"]}'::jsonb, '{"answer":1}'::jsonb, '« car la population vieillit ».'), ('qmw0ouu