with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co19urt06v', 'practice', 'Écoute B1 : un entretien radio', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-entretien-radio.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un sapeur-pompier (nom masculin) : lính cứu hoả\n• une caserne (nom féminin) : trạm cứu hoả\n• un concours (nom masculin) : kỳ thi tuyển\n• une garde (nom féminin) : ca trực\n• une intervention (nom féminin) : lần can thiệp, xuất quân","explications":"• Phỏng vấn có ba câu hỏi: vì sao chọn nghề, một ngày làm việc, khó khăn. Chia giấy nháp thành ba phần.\n• « Contrairement à ce qu''on croit » báo trước một thông tin bất ngờ: đề rất hay hỏi.","isPremium":true,"price":19000,"kyNang":"B1-CO-4","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T17:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy04e', 'b1co19urt06v', 1, 'qcm', 'Quel est le métier de Lucie ?', '{"options":["infirmière","sapeuse-pompière","professeure de sport"]}'::jsonb, '{"answer":1}'::jsonb, '« Lucie Garnier est sapeuse-pompière à Grenoble ».'), ('qmw0ouufy04f', 'b1co19urt06v', 2, 'fill', 'Complétez avec ce que vous entendez : Lucie Garnier est sapeuse-pompière à Grenoble depuis ______ ans.', '{}'::jsonb, '{"accepted":"six|6"}'::jsonb, 'Six là 6.'), ('qmw0ouufy04g', 'b1co19urt06v', 3, 'qcm', 'Pourquoi a-t-elle choisi ce métier ?', '{"options":["elle voulait aider les gens depuis l''enfance","pour le salaire","parce qu''elle aime le sport"]}'::jsonb, '{"answer":0}'::jsonb, '« Depuis toute petite, je voulais aider les gens ».'), ('qmw0ouufy04h', 'b1co19urt06v', 4, 'qcm', 'Son père…', '{"options":["était médecin","travaillait comme cuisinier à la caserne","était pompier volontaire"]}'::jsonb, '{"answer":2}'::jsonb, '« Mon père était pompier volontaire ».'), ('qmw0ouufy04i', 'b1co19urt06v', 5, 'fill', 'Complétez avec ce que vous entendez : Nous travaillons par gardes de ______ heures.', '{}'::jsonb, '{"accepted":"vingt-quatre|24|vingt quatre"}'::jsonb, 'Ca trực 24 giờ.'), ('qmw0ouufy04j', 'b1co19urt06v', 6, 'qcm', 'La plupart des interventions concernent…', '{"options":["des accidents de la route","des personnes malades ou blessées","des incendies"]}'::jsonb, '{"answer":1}'::jsonb, '« La plupart du temps, nous aidons des personnes malades ou blessées ». Incendies chỉ khoảng 10 %.'), ('qmw0ouufy04k', 'b1co19urt06v', 7, 'qcm', 'Au début, certains collègues…', '{"options":["l''aidaient beaucoup","refusaient de travailler avec elle","doutaient d''elle"]}'::jsonb, '{"answer":2}'::jsonb, '« Au début, certains collègues doutaient de moi ».'), ('qmw0ouufy04l', 'b1co19urt06v', 8, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy04n","texte":"nous sommes quatre femmes"},{"id":"emw0ouufy04m","texte":"Dans ma caserne,"},{"id":"emw0ouufy04o","texte":"sur soixante."}]}'::jsonb, '{"elements":[{"id":"emw0ouufy04m","texte":"Dans ma caserne,"},{"id":"emw0ouufy04n","texte":"nous sommes quatre femmes"},{"id":"emw0ouufy04o","texte":"sur soixante."}]}'::jsonb, '4 nữ trên tổng số 60 người.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co20zfr06w', 'practice', 'Écoute B1 : le retour des livres papier', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-livres-papier.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une liseuse (nom féminin) : máy đọc sách\n• revenir à la mode (expression) : thịnh hành trở lại\n• une librairie (nom féminin) : hiệu sách\n• prêter (verbe) : cho mượn\n• se déconnecter (verbe) : ngắt kết nối","explications":"• « On pensait que… Pourtant… »: ý chính nằm sau pourtant.\n• Librairie là hiệu sách, bibliothèque mới là thư viện.","isPremium":true,"price":19000,"kyNang":"B1-CO-5","vong":"hoc","thuTu":4}'::jsonb, '2026-11-03T17:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy04p', 'b1co20zfr06w', 1, 'qcm', 'Quel est le sujet du reportage ?', '{"options":["les jeunes reviennent au livre papier","les librairies ferment","les liseuses sont moins chères"]}'::jsonb, '{"answer":0}'::jsonb, '« chez les jeunes, il revient à la mode ».'), ('qmw0ouufy04q', 'b1co20zfr06w', 2, 'fill', 'Complétez avec ce que vous entendez : Depuis ______ ans, je vois de plus en plus de clients de quinze à vingt-cinq ans.', '{}'::jsonb, '{"accepted":"trois|3"}'::jsonb, 'Trois là 3.'), ('qmw0ouufy04r', 'b1co20zfr06w', 3, 'qcm', 'Comment ces jeunes découvrent-ils les romans ?', '{"options":["à la télévision","à l''école","sur les réseaux sociaux"]}'::jsonb, '{"answer":2}'::jsonb, '« Ils découvrent des romans sur les réseaux sociaux ».'), ('qmw0ouufy04s', 'b1