with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co213t406x', 'practice', 'Écoute B1 : le sport à l''école', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-sport-ecole.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la rentrée (nom féminin) : ngày khai giảng\n• un bilan (nom masculin) : tổng kết\n• sceptique (adjectif) : hoài nghi\n• se concentrer (verbe) : tập trung\n• un défi (nom masculin) : thử thách","explications":"• Radio tốc độ thật: lần nghe đầu bắt ý, lần hai mới bắt số.\n• « J''étais sceptique au début. Mais… »: thái độ thay đổi, câu hỏi thường hỏi cả hai thời điểm.","isPremium":true,"price":19000,"kyNang":"B1-CO-5","vong":"on","thuTu":5}'::jsonb, '2026-11-03T17:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy04y', 'b1co213t406x', 1, 'fill', 'Complétez avec ce que vous entendez : Les écoles primaires de la région testent ______ minutes d''activité physique chaque jour.', '{}'::jsonb, '{"accepted":"trente|30"}'::jsonb, 'Trente là 30.'), ('qmw0ouufy04z', 'b1co213t406x', 2, 'qcm', 'Ces activités remplacent-elles les cours d''éducation physique ?', '{"options":["oui, un jour sur deux","non, elles s''ajoutent à ces cours","oui, complètement"]}'::jsonb, '{"answer":1}'::jsonb, '« en plus des cours d''éducation physique ».'), ('qmw0ouufy050', 'b1co213t406x', 3, 'qcm', 'Au début, le professeur était…', '{"options":["sceptique","enthousiaste","indifférent"]}'::jsonb, '{"answer":0}'::jsonb, '« Honnêtement, j''étais sceptique au début ».'), ('qmw0ouufy051', 'b1co213t406x', 4, 'qcm', 'Quel résultat observe-t-il ?', '{"options":["les enfants se concentrent mieux","les notes en sport augmentent","les enfants sont plus fatigués"]}'::jsonb, '{"answer":0}'::jsonb, '« Les enfants sont plus calmes l''après-midi et ils se concentrent mieux ».'), ('qmw0ouufy052', 'b1co213t406x', 5, 'qcm', 'Quelle difficulté mentionne-t-il ?', '{"options":["le manque de matériel","quand il pleut, il faut rester dans une petite classe","les parents ne sont pas d''accord"]}'::jsonb, '{"answer":1}'::jsonb, '« quand il pleut, faire bouger vingt-huit élèves dans une petite classe, c''est un vrai défi ».'), ('qmw0ouufy053', 'b1co213t406x', 6, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy055","texte":"faire bouger vingt-huit élèves"},{"id":"emw0ouufy057","texte":"c''est un vrai défi"},{"id":"emw0ouufy056","texte":"dans une petite classe,"},{"id":"emw0ouufy054","texte":"quand il pleut,"}]}'::jsonb, '{"elements":[{"id":"emw0ouufy054","texte":"quand il pleut,"},{"id":"emw0ouufy055","texte":"faire bouger vingt-huit élèves"},{"id":"emw0ouufy056","texte":"dans une petite classe,"},{"id":"emw0ouufy057","texte":"c''est un vrai défi"}]}'::jsonb, 'Điều kiện, việc phải làm, rồi nhận xét.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co227n806y', 'practice', 'Écoute B1 : le magazine de société', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le document, puis répondez aux questions. Pour les phrases à compléter, écrivez le mot que vous entendez.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-magazine-societe.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la colocation (nom féminin) : ở ghép\n• une génération (nom féminin) : thế hệ\n• rendre service (expression) : giúp đỡ\n• rassuré, rassurée (adjectif) : yên tâm\n• un binôme (nom masculin) : cặp đôi","explications":"• Hai người kể, mỗi người một góc nhìn: ghi riêng « Inès » và « Robert ».\n• Ai dạy ai: apprendre à quelqu''un à faire quelque chose. Nghe kỹ chủ ngữ.","isPremium":true,"price":19000,"kyNang":"B1-CO-5","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T17:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy058', 'b1co227n806y', 1, 'qcm', 'Quel est le thème de l''émission ?', '{"options":["le prix des studios à Paris","les maisons de retraite","la colocation entre une personne âgée et un étudiant"]}'::jsonb, '{"answer":2}'::jsonb, '« la colocation entre générations ».'), ('qmw0ouufy059', 'b1co227n806y', 2, 'fill', 'Complétez avec ce que vous entendez : Je paie ______ euros par mois.', '{}'::jsonb, '{"accepted":"cent cinquante|150|cent-cinquante"}'::jsonb, '150 euro, so với ít nhất 800 euro cho một studio.'), ('qmw0ouufy05a', 'b1co227n806y', 3, 'qcm', 'En échange, Inès…', '{"options":["dîne avec Robert trois soirs par semaine","fait le ménage tous les jours","paie l''électricité"]}'::jsonb, '{"answer":0}'::jsonb, '« je dîne avec Robert trois soirs par semaine et je fais quelques courses ».'), ('qmw0ouufy05b', 'b1co227n806y', 4, 'qcm', 'Comment Inès vit-elle ces services ?', '{"options":["comme un travail fatigant","comme une obligation","comme un plaisir"]}'::jsonb, '{"answer":2}'::jsonb, '« Ce n''est pas une obligation pour moi, c''est devenu un vrai plaisir ».'), ('qmw0ouufy05c', 'b1co227n806y', 5, 'qcm', 'Pourquoi Robert voulait-il un colocataire ?', '{"options":["il avait besoin d''argent","la maison était trop silencieuse","sa fille le lui a demandé"]}'::jsonb, '{"answer":1}'::jsonb, '« Depuis la mort de ma femme, la maison était trop silencieuse ».'), ('qmw0ouufy05d', 'b1co227n806y', 6, 'qcm', 'Qu''est-ce que Robert apprend à Inès ?', '{"options":["à conduire","à utiliser son téléphone","à cuisiner"]}'::jsonb, '{"answer":2}'::jsonb, '« Et moi, je lui apprends à cuisiner ». Inès dạy Robert dùng điện thoại.'), ('qmw0ouufy05e', 'b1co227n806y', 7, 'qcm', 'Au début, la fille de Robert était…', '{"options":["indifférente","enthousiaste","inquiète"]}'::jsonb, '{"answer":2}'::jsonb, '« Ma fille était inquiète au début ».'), ('qmw0ouufy05f', 'b1co227n806y', 8, 'ordre', 'Remettez les morceaux dans l''ordre pour retrouver la phrase entendue.', '{"elements":[{"id":"emw0ouufy05i","texte":"a déjà formé"},{"id":"emw0ouufy05g","texte":"L''association"},{"id":"emw0ouufy05j","texte":"plus de deux cents binômes"},{"id":"emw0ouufy05h","texte":"qui les a mis en relation"}]}'::jsonb, '{"elements":[{"id":"emw0ouufy05g","texte":"L''association"},{"id":"emw0ouufy05h","texte":"qui les a mis en relation"},{"id":"emw0ouufy05i","texte":"a déjà formé"},{"id":"emw0ouufy05j","texte":"plus de deux cents binômes"}]}'::jsonb, 'Chủ ngữ có mệnh đề qui đi kèm, rồi động từ.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co23bti06z', 'practice', 'Écoute B1 : prendre des notes vite', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Répondez d''abord aux questions sur les abréviations. Puis écoutez le message et notez les informations demandées.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-notes-vite.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une abréviation (nom féminin) : chữ viết tắt\n• un centre de formation (expression) : trung tâm đào tạo\n• durer (verbe) : kéo dài\n• une photo d''identité (expression) : ảnh thẻ\n• pour toute question (expression) : mọi thắc mắc","explications":"• Ghi số bằng chữ số, không viết chữ: 18 h 30, 220 €.\n• Viết tắt quen thuộc: RDV, qqch, qqn, + (et), → (donc), ≠ (différent).","kyNang":"B1-CO-6","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T17:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy05k', 'b1co23bti06z', 1, 'qcm', 'Pour noter vite « rendez-vous », on écrit souvent…', '{"options":["RDV","RVS","RZV"]}'::jsonb, '{"answer":0}'::jsonb, 'RDV là viết tắt quen thuộc của rendez-vous.'), ('qmw0ouufy05l', 'b1co23bti06z', 2, 'qcm', 'Dans des notes, « qqch » veut dire…', '{"options":["quelque chose","quelquefois","quelqu''un"]}'::jsonb, '{"answer":0}'::jsonb, 'qqch: quelque chose; qqn: quelqu''un.'), ('qmw0ouufy05m', 'b1co23bti06z', 3, 'qcm', 'Dans des notes, le signe « + » à la place d''un mot veut souvent dire…', '{"options":["environ","moins","plus, et"]}'::jsonb, '{"answer":2}'::jsonb, '+ thay cho plus hoặc et; ≈ mới là environ.'), ('qmw0ouufy05n', 'b1co23bti06z', 4, 'fill', 'Date du début du cours : lundi ______', '{}'::jsonb, '{"accepted":"quatorze octobre|14 octobre|14/10|14"}'::jsonb, 'Lundi quatorze octobre.'), ('qmw0ouufy05o', 'b1co23bti06z', 5, 'fill', 'Heure du cours : ______', '{}'::jsonb, '{"accepted":"dix-huit heures trente|18 h 30|18h30|18:30|18 h 30 min|18.30"}'::jsonb, 'Ghi bằng số cho nhanh: 18 h 30.'), ('qmw0ouufy05p', 'b1co23bti06z', 6, 'fill', 'Salle : ______', '{}'::jsonb, '{"accepted":"douze|12|salle 12|salle douze"}'::jsonb, 'Salle douze, ở tầng hai.'), ('qmw0ouufy05q', 'b1co23bti06z', 7, 'fill', 'Prix du cours : ______', '{}'::jsonb, '{"accepted":"deux cent vingt euros|220|220 €|220 euros|220€|deux cent vingt"}'::jsonb, '220 €.'), ('qmw0ouufy05r', 'b1co23bti06z', 8, 'fill', 'À apporter : ______', '{}'::jsonb, '{"accepted":"une photo d''identité|photo d''identité|une photo|photo"}'::jsonb, '« N''oubliez pas d''apporter une photo d''identité ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co24g6q070', 'practice', 'Écoute B1 : les mots importants', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez l''information. Notez les mots importants dans chaque case.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-mots-importants.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le tri (nom masculin) : phân loại rác\n• un emballage (nom masculin) : bao bì\n• un conteneur (nom masculin) : thùng chứa lớn\n• ramasser (verbe) : thu gom\n• réduire de moitié (expression) : giảm một nửa","explications":"• Từ khoá thường là danh từ và con số: bỏ qua le, la, de khi ghi.\n• Mỗi ô một thông tin: đọc nhãn ô trước khi nghe để biết cần bắt từ gì.","isPremium":true,"price":19000,"kyNang":"B1-CO-6","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T17:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy05s', 'b1co24g6q070', 1, 'fill', 'Date du changement : ______', '{}'::jsonb, '{"accepted":"premier février|1er février|1 février|1/02|01/02"}'::jsonb, '« À partir du premier février ».'), ('qmw0ouufy05t', 'b1co24g6q070', 2, 'fill', 'Poubelle pour le plastique (couleur) : ______', '{}'::jsonb, '{"accepted":"jaune|la poubelle jaune"}'::jsonb, '« iront dans la poubelle jaune ».'), ('qmw0ouufy05u', 'b1co24g6q070', 3, 'fill', 'Jour de ramassage des déchets de cuisine : ______', '{}'::jsonb, '{"accepted":"mardi|le mardi"}'::jsonb, '« seront ramassés le mardi ».'), ('qmw0ouufy05v', 'b1co24g6q070', 4, 'fill', 'Où trouver le bac marron ? ______', '{}'::jsonb, '{"accepted":"en mairie|à la mairie|mairie|la mairie"}'::jsonb, '« distribué gratuitement en mairie ».'), ('qmw0ouufy05w', 'b1co24g6q070', 