with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co25llo071', 'practice', 'Écoute B1 : notes et questions', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez une première fois en prenant des notes sur une feuille, sans regarder les questions. Puis lisez les questions et répondez avec vos notes.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-notes-questions.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un salon (nom masculin) : hội chợ, triển lãm\n• le parc des expositions (expression) : khu triển lãm\n• un atelier (nom masculin) : buổi thực hành\n• un exemplaire (nom masculin) : bản\n• obligatoire (adjectif) : bắt buộc","explications":"• Không xem câu hỏi thì ghi theo khung: quand, où, qui, quoi, combien, comment.\n• Thông tin sau « mais » thường là điều kiện bắt buộc.","isPremium":true,"price":19000,"kyNang":"B1-CO-6","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T17:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy05x', 'b1co25llo071', 1, 'fill', 'Date du salon : ______', '{}'::jsonb, '{"accepted":"jeudi vingt-trois mars|jeudi 23 mars|23 mars|vingt-trois mars|23/03"}'::jsonb, '« le jeudi vingt-trois mars ».'), ('qmw0ouufy05y', 'b1co25llo071', 2, 'qcm', 'Combien d''entreprises seront présentes ?', '{"options":["plus de 200","environ 100","plus de 120"]}'::jsonb, '{"answer":2}'::jsonb, '« Plus de cent vingt entreprises seront présentes ».'), ('qmw0ouufy05z', 'b1co25llo071', 3, 'qcm', 'Les ateliers servent à…', '{"options":["préparer son CV et les entretiens","apprendre l''informatique","trouver un logement"]}'::jsonb, '{"answer":0}'::jsonb, '« préparer son CV et de s''entraîner aux entretiens ».'), ('qmw0ouufy