with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1co27tsr073', 'practice', 'Écoute B1 : un long reportage', 'B1', array['Écoute']::text[], 'practice', null, null, '<p>Écoutez le reportage en prenant des notes. Puis répondez à toutes les questions avec vos notes.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-long-reportage.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un train de nuit (expression) : tàu đêm\n• relier (verbe) : nối\n• une couchette (nom féminin) : giường nằm trên tàu\n• à partir de (expression) : từ (giá thấp nhất)\n• un défaut (nom masculin) : khuyết điểm","explications":"• Bài dài: chia giấy theo các phần của phóng viên (thông tin, lý do, nhân chứng).\n• « À partir de » đi với giá thấp nhất: đừng chọn số khác vì nghe gần giống.","isPremium":true,"price":19000,"kyNang":"B1-CO-6","vong":"chot","thuTu":5}'::jsonb, '2026-11-03T17:00:26.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0ouufy067', 'b1co27tsr073', 1, 'fill', 'Durée du trajet Paris-Berlin : ______', '{}'::jsonb, '{"accepted":"douze heures|12 heures|12 h|12h|12"}'::jsonb, '« en douze heures ».'), ('qmw0ouufy068', 'b1co27tsr073', 2, 'fill', 'Fréquence : ______ par semaine', '{}'::jsonb, '{"accepted":"trois fois|3 fois|trois|3"}'::jsonb, '« trois fois par semaine ».'), ('qmw0ouufy069', 'b1co27tsr073', 3, 'qcm', 'Prix minimum d''une couchette :', '{"options":["17 €","90 €","70 €"]}'::jsonb, '{"answer":2}'::jsonb, '« des couchettes à partir de soixante-dix euros ».'), ('qmw0ouufy06a', 'b1co27tsr073', 4, 'qcm', 'Quelles sont les deux raisons du retour des trains de nuit ?', '{"options":["la vitesse et le confort","l''environnement et l''économie d''une nuit d''hôtel","le prix des repas et la sécurité"]}'::jsonb, '{"answer":1}'::jsonb, '« D''abord, pour l''environnement… Ensuite, parce que les voyageurs économisent une nuit d''hôtel ».'), ('qmw0ouufy06b', 'b1co27tsr073', 5, 'qcm', 'Pourquoi le passager ne prend-il plus l''avion ?', '{"options":["il perdait presque autant de temps","il a peur de l''avion","l''avion est trop cher"]}'::jsonb, '{"answer":0}'::jsonb, '« je perdais presque autant de temps ».'), ('qmw0ouufy06c', 'b1co27tsr073', 6, 'fill', 'Complétez avec ce que vous entendez : Quinze euros pour un sandwich, c''est ______ !', '{}'::jsonb, '{"accepted":"trop"}'::jsonb, 'Lời chê duy nhất của hành khách.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare n int;
begin
  select count(*) into n from public.exercises where id like 'b1co%';
  if n <> 27 then raise exception 'có % bài Nghe B1 mới, cần 27', n; end if;
end $$;
